#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAXN 100005
#define LOG 17
#define MAXB 500

int p[MAXN];
int head[MAXN], to[MAXN], nxt[MAXN];
int edge_cnt = 0;

void add_edge(int u, int v) {
    to[++edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt;
}

int tin[MAXN], tout[MAXN], timer;
int last_time[MAXN];
int parent_static[MAXN];
int depth[MAXN];
int up[MAXN][LOG];

int type_arr[50005];
int v_arr[50005];
int k_arr[50005];

int cmp_uint64(const void *a, const void *b) {
    uint64_t x = *(uint64_t*)a;
    uint64_t y = *(uint64_t*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main() {
    int N;
    scanf("%d", &N);
    p[1] = 0;
    for (int i = 2; i <= N; i++) {
        scanf("%d", &p[i]);
        add_edge(p[i], i);
    }

    // compute tin/tout using iterative DFS
    int st_node[MAXN], st_state[MAXN];
    int st_top = 0;
    st_node[st_top] = 1; st_state[st_top] = 0; st_top++;
    timer = 0;
    while (st_top > 0) {
        st_top--;
        int u = st_node[st_top];
        int state = st_state[st_top];
        if (state == 0) {
            tin[u] = ++timer;
            st_node[st_top] = u; st_state[st_top] = 1; st_top++;
            for (int e = head[u]; e != 0; e = nxt[e]) {
                int v = to[e];
                st_node[st_top] = v; st_state[st_top] = 0; st_top++;
            }
        } else {
            tout[u] = timer;
        }
    }

    int Q;
    scanf("%d", &Q);
    for (int i = 0; i < Q; i++) {
        scanf("%d", &type_arr[i]);
        if (type_arr[i] == 2) {
            scanf("%d", &v_arr[i]);
            k_arr[i] = 0;
        } else {
            scanf("%d %d", &v_arr[i], &k_arr[i]);
        }
    }

    memset(last_time, 0, sizeof(last_time));
    int global_time = 0;

    const int B = 400;
    int num_blocks = (Q + B - 1) / B;

    for (int block = 0; block < num_blocks; block++) {
        int start = block * B;
        int end = start + B;
        if (end > Q) end = Q;

        // Build static tree for this block
        struct State {
            int u;
            int max_t;
            int max_n;
        };
        struct State stack[MAXN];
        int top = 0;
        stack[top].u = 1;
        stack[top].max_t = last_time[1];
        stack[top].max_n = 1;
        top++;
        while (top > 0) {
            top--;
            struct State s = stack[top];
            int u = s.u;
            if (u != 1) {
                parent_static[u] = (s.max_t > 0) ? s.max_n : p[u];
            }
            int new_max_t = s.max_t;
            int new_max_n = s.max_n;
            if (last_time[u] > new_max_t) {
                new_max_t = last_time[u];
                new_max_n = u;
            }
            for (int e = head[u]; e != 0; e = nxt[e]) {
                int v = to[e];
                stack[top].u = v;
                stack[top].max_t = new_max_t;
                stack[top].max_n = new_max_n;
                top++;
            }
        }

        // Compute depth and binary lifting table
        depth[1] = 0;
        for (int j = 0; j < LOG; j++) up[1][j] = 1;
        for (int u = 2; u <= N; u++) {
            depth[u] = depth[parent_static[u]] + 1;
            up[u][0] = parent_static[u];
        }
        for (int j = 1; j < LOG; j++) {
            for (int u = 2; u <= N; u++) {
                up[u][j] = up[ up[u][j-1] ][j-1];
            }
        }

        // Process operations in the current block
        int updates_node[MAXB];
        int updates_seq[MAXB];
        int updates_count = 0;
        int seq = 0;

        for (int op = start; op < end; op++) {
            if (type_arr[op] == 2) {
                int v = v_arr[op];
                global_time++;
                last_time[v] = global_time;
                seq++;
                updates_node[updates_count] = v;
                updates_seq[updates_count] = seq;
                updates_count++;
            } else {
                int v = v_arr[op];
                int k = k_arr[op];
                uint64_t filtered[MAXB];
                int fcount = 0;
                for (int i = 0; i < updates_count; i++) {
                    int u = updates_node[i];
                    if (u != v && tin[u] <= tin[v] && tout[u] >= tout[v]) {
                        uint64_t val = ((uint64_t)tin[u] << 40) |
                                       ((uint64_t)updates_seq[i] << 20) |
                                       (uint64_t)u;
                        filtered[fcount++] = val;
                    }
                }
                if (fcount > 0) {
                    qsort(filtered, fcount, sizeof(uint64_t), cmp_uint64);
                }
                int U[MAXB];
                int m = 0;
                int max_seq = 0;
                for (int i = 0; i < fcount; i++) {
                    uint64_t val = filtered[i];
                    int s = (val >> 20) & 0xFFFFF;
                    int node = val & 0xFFFFF;
                    if (s > max_seq) {
                        U[m++] = node;
                        max_seq = s;
                    }
                }
                int ans;
                if (m == 0) {
                    int u = v;
                    int kk = k;
                    for (int j = 0; j < LOG; j++) {
                        if (kk & (1 << j)) {
                            u = up[u][j];
                        }
                    }
                    ans = u;
                } else {
                    if (k <= m) {
                        ans = U[m - k];
                    } else {
                        int rem = k - m;
                        int w1 = U[0];
                        int u = w1;
                        int kk = rem;
                        for (int j = 0; j < LOG; j++) {
                            if (kk & (1 << j)) {
                                u = up[u][j];
                            }
                        }
                        ans = u;
                    }
                }
                printf("%d\n", ans);
            }
        }
    }

    return 0;
}
